// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {
  DATATYPE_FACET_ID,
  LANGUAGE_FACET_ID,
  intrinsicFacetSparqlFilter,
} from "../../../main/frontend/graph-explorer/graph-filters.ts";
import {
  INTERNAL_BNODE_NODE_PREFIX,
  escapedSparqlString,
  isSafeSparqlIri,
} from "../../../main/frontend/graph-explorer/rdf-terms.ts";
import { parseWorkspacePayload } from "../../../main/frontend/graph-explorer/workspace.ts";

/** One rule decides which IRIs generated SPARQL may hold and how strings are escaped, wherever SPARQL is written. */
const IRI_SAMPLES = [
  "urn:a",
  "http://example.org/a#b",
  "urn:é",
  "http://example.org/a b",
  "http://example.org/<a>",
  'http://example.org/a"b',
  "http://example.org/{a}",
  "http://example.org/a|b",
  "http://example.org/a^b",
  "http://example.org/a`b",
  "http://example.org/a\\b",
  "urn:a\tb",
  "urn:a\nb",
  "no-scheme",
  "1urn:a",
  "",
];

test("the datatype filter admits exactly the IRIs the shared rule calls safe", () => {
  for (const iri of IRI_SAMPLES) {
    const filter = intrinsicFacetSparqlFilter(DATATYPE_FACET_ID, new Set([iri]));
    assert.equal(filter.includes(`<${iri}>`), isSafeSparqlIri(iri), JSON.stringify(iri));
    if (!isSafeSparqlIri(iri)) assert.equal(filter, "FILTER(false)", JSON.stringify(iri));
  }
});

test("a stored workspace admits exactly the IRIs and predicates the shared rule calls safe", () => {
  for (const iri of IRI_SAMPLES) {
    const node = parseWorkspacePayload(JSON.stringify({ graph: { nodes: [{ id: iri, label: "x", kind: "iri" }], edges: [], revision: 0 } }));
    assert.equal(node !== null, isSafeSparqlIri(iri), `node ${JSON.stringify(iri)}`);
    const edge = parseWorkspacePayload(JSON.stringify({ graph: {
      nodes: [{ id: "urn:s", label: "s", kind: "iri" }, { id: "urn:o", label: "o", kind: "iri" }],
      edges: [{ id: "e", source: "urn:s", predicate: iri, label: "p", target: "urn:o" }],
      revision: 0,
    } }));
    assert.equal(edge !== null, isSafeSparqlIri(iri), `predicate ${JSON.stringify(iri)}`);
  }
});

test("legacy blank IDs in a stored workspace use the shared internal prefix", () => {
  const payload = parseWorkspacePayload(JSON.stringify({ graph: { nodes: [
    { id: "_:b1", label: "b1", kind: "blank" },
    { id: "urn:o", label: "o", kind: "iri" },
  ], edges: [{ id: "e", source: "_:b1", predicate: "urn:p", label: "p", target: "urn:o" }], revision: 0 } }));

  assert.ok(payload);
  assert.equal(payload.graph.nodes[0].id, `${INTERNAL_BNODE_NODE_PREFIX}b1`);
  assert.equal(payload.graph.edges[0].source, `${INTERNAL_BNODE_NODE_PREFIX}b1`);
});

test("the language filter escapes its values like every other generated SPARQL string", () => {
  const values = ["en\u0001x", 'quote"d', "back\\slash", "line\nbreak", "tab\tx", "del\u007fx", "c1\u0085x"];

  const filter = intrinsicFacetSparqlFilter(LANGUAGE_FACET_ID, new Set(values));

  for (const value of values) {
    assert.ok(filter.includes(`"${escapedSparqlString(value.toLowerCase())}"`), JSON.stringify(value));
  }
  assert.doesNotMatch(filter, /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f]/, "no raw control characters");
  assert.doesNotMatch(filter, /[\n\t]/, "line breaks and tabs are escaped too");
});

test("the shared escaper writes every control character as an escape SPARQL reads back", () => {
  for (let code = 0; code <= 0x9f; code++) {
    if (code >= 0x20 && code < 0x7f) continue;
    const escaped = escapedSparqlString(String.fromCharCode(code));
    assert.match(escaped, /^\\(?:[rn]|u[0-9A-F]{4})$/, `U+${code.toString(16)}`);
  }
  assert.equal(escapedSparqlString('a"b\\c'), 'a\\"b\\\\c');
});
